CREATE OR REPLACE TABLE I2B2_SANDBOX_GPC.I2B2DATA.COVID_FACT AS
SELECT * FROM I2B2_SANDBOX_GPC.I2B2DATA.DIAGNOSIS_FACT
UNION ALL
SELECT * FROM I2B2_SANDBOX_GPC.I2B2DATA.PROCEDURE_FACT
UNION ALL
