create or replace table I2B2_SANDBOX_GPC.I2B2DATA.TUMOR_FACT(
	ENCOUNTER_NUM,
	PATIENT_NUM,
	CONCEPT_CD,
	PROVIDER_ID,
	START_DATE,
	MODIFIER_CD,
	INSTANCE_NUM,
	VALTYPE_CD,
	TVAL_CHAR,
	NVAL_NUM,
	VALUEFLAG_CD,
	QUANTITY_NUM,
	UNITS_CD,
	END_DATE,
	LOCATION_CD,
	OBSERVATION_BLOB,
	CONFIDENCE_NUM,
	UPDATE_DATE,
	DOWNLOAD_DATE,
	IMPORT_DATE,
	SOURCESYSTEM_CD,
	UPLOAD_ID
) as
(
    select 
        -1 :: NUMBER(38, 0)                                                                              as ENCOUNTER_NUM
        , PATIENT_NUM                                                                                    as PATIENT_NUM
        ,concat('NAACCR|', split_part(concept, '_N', -1), ':', coalesce(concept_cd, ''))                 as CONCEPT_CD
        ,'@'                                                                                             as PROVIDER_ID
        ,DATE_CASE_INITIATED_N2085 :: TIMESTAMP                                                          as START_DATE
        ,'@'                                                                                             as MODIFIER_CD
        ,1                                                                                               as INSTANCE_NUM
        ,''                                                                                              as VALTYPE_CD
        ,''                                                                                              as TVAL_CHAR
        ,cast(null as  integer)                                                                          as NVAL_NUM
        ,''                                                                                              as VALUEFLAG_CD
        ,cast(null as  integer)                                                                          as QUANTITY_NUM
        ,'@'                                                                                             as UNITS_CD
        ,cast(DATE_CASE_COMPLETED_N2090 as TIMESTAMP)                                                    as END_DATE
        ,'@'                                                                                             as LOCATION_CD
        ,cast(null as  text)                                                                             as OBSERVATION_BLOB
        ,cast(null as  integer)                                                                          as CONFIDENCE_NUM
        ,CURRENT_TIMESTAMP                                                                               as UPDATE_DATE
        ,CURRENT_TIMESTAMP                                                                               as DOWNLOAD_DATE
        ,CURRENT_TIMESTAMP                                                                               as IMPORT_DATE
        ,cast(null as VARCHAR(50))                                                                       as SOURCESYSTEM_CD
        ,cast(null as  integer)                                                                          as UPLOAD_ID
    from CDM_DATALAKE.GPC.GPC_DEID_TUMOR
